-- The balance due and the paid flags count the money given back for cancelled lines (2026-11, review round 2).
-- An order paid in full, with a line cancelled and refunded and an item added in its place, read as paid with
-- nothing due, so the added item was never charged. What counts as received is now the payments less the refunds
-- and lost disputes, but never more than the cancelled lines' refund credit (each cancelled line's refundCents, at
-- most its total with its tax when tax is added on top): a goodwill refund, or one on a line still on the order,
-- never puts a balance back (db.js balanceReceivedSql_).
--   orders.paid, paidForWork, paidAt  worked out again here for the orders that have a cancelled line with a refund,
--                                     with the same statement the code uses (db.js paidRefreshSql_; test341 checks
--                                     the two are the same).
-- DATA ONLY: no table, column or index changes; schema.sql is unchanged. Safe to run again.
UPDATE orders SET
    paidAt = CASE WHEN MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(rushFeeCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN COALESCE(rushFeeTaxCents, 0) ELSE 0 END) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) = 0 THEN paidAt
                  WHEN (COALESCE((SELECT SUM(amountCents) FROM order_payments WHERE orderId = orders.orderId AND kind = 'payment' AND voidedAt IS NULL), 0) - MAX(0, MIN(
    COALESCE((SELECT -SUM(amountCents) FROM order_payments WHERE orderId = orders.orderId AND kind IN ('refund', 'dispute') AND voidedAt IS NULL), 0),
    COALESCE((SELECT SUM(MIN(refundCents, lineTotalCents + (CASE WHEN orders.taxMode = 'exclusive' THEN COALESCE(taxCents, 0) ELSE 0 END)))
      FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NOT NULL AND refundCents > 0), 0)))) >= MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(rushFeeCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN COALESCE(rushFeeTaxCents, 0) ELSE 0 END) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) THEN (CASE WHEN paid = 1 THEN paidAt ELSE COALESCE((SELECT MAX(receivedAt) FROM order_payments WHERE orderId = orders.orderId AND kind = 'payment' AND voidedAt IS NULL), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) END)
                  ELSE (CASE WHEN paid = 1 THEN NULL ELSE paidAt END) END,
    paidForWork = CASE WHEN MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(rushFeeCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN COALESCE(rushFeeTaxCents, 0) ELSE 0 END) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) = 0 THEN paid WHEN MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) = 0 THEN 1
                       WHEN (COALESCE((SELECT SUM(amountCents) FROM order_payments WHERE orderId = orders.orderId AND kind = 'payment' AND voidedAt IS NULL), 0) - MAX(0, MIN(
    COALESCE((SELECT -SUM(amountCents) FROM order_payments WHERE orderId = orders.orderId AND kind IN ('refund', 'dispute') AND voidedAt IS NULL), 0),
    COALESCE((SELECT SUM(MIN(refundCents, lineTotalCents + (CASE WHEN orders.taxMode = 'exclusive' THEN COALESCE(taxCents, 0) ELSE 0 END)))
      FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NOT NULL AND refundCents > 0), 0)))) >= MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) THEN 1 ELSE 0 END,
    paid = CASE WHEN MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(rushFeeCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN COALESCE(rushFeeTaxCents, 0) ELSE 0 END) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) = 0 THEN paid WHEN (COALESCE((SELECT SUM(amountCents) FROM order_payments WHERE orderId = orders.orderId AND kind = 'payment' AND voidedAt IS NULL), 0) - MAX(0, MIN(
    COALESCE((SELECT -SUM(amountCents) FROM order_payments WHERE orderId = orders.orderId AND kind IN ('refund', 'dispute') AND voidedAt IS NULL), 0),
    COALESCE((SELECT SUM(MIN(refundCents, lineTotalCents + (CASE WHEN orders.taxMode = 'exclusive' THEN COALESCE(taxCents, 0) ELSE 0 END)))
      FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NOT NULL AND refundCents > 0), 0)))) >= MAX(0, COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(shippingCostCents, 0) ELSE 0 END) + (CASE WHEN COALESCE((SELECT SUM(lineTotalCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) > 0 THEN COALESCE(rushFeeCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN COALESCE(rushFeeTaxCents, 0) ELSE 0 END) ELSE 0 END) - COALESCE(discountCents, 0) + (CASE WHEN taxMode = 'exclusive' THEN MAX(0, COALESCE((SELECT SUM(taxCents) FROM order_items WHERE orderId = orders.orderId AND cancelDate IS NULL), 0) - COALESCE(discountTaxCents, 0)) ELSE 0 END)) THEN 1 ELSE 0 END
  WHERE orderId IN (SELECT orderId FROM order_items WHERE cancelDate IS NOT NULL AND refundCents > 0);
